// Package boundaryplan plans TEST ONLY D-140 added probes. It does no I/O.
package boundaryplan

import (
	"fmt"
	"slices"
	"sort"
)

type Sample struct {
	PacketID int   `json:"packet_id"`
	Send     int64 `json:"send_mono_ns,string"`
	Ingress  int64 `json:"ingress_mono_ns,string"`
	Egress   int64 `json:"egress_mono_ns,string"`
	Latency  int64 `json:"latency_ns,string"`
	Transit  int64 `json:"transit_ns,string"`
}

type Send struct {
	At    int64  `json:"scheduled_mono_ns,string"`
	Phase string `json:"phase"`
}

type Candidate struct {
	At         int64  `json:"scheduled_mono_ns,string"`
	ExcludedBy []Send `json:"excluded_by_original_sends"`
}

// Plan uses exactly the checkpoint's samples and remaining original sends. It
// preserves the maximum-transit spacing rule: no sample is discounted, even a
// far-from-boundary capture-read outlier. This can make every candidate collide
// with the original cadence (F24-01); that is explicitly unqualified, never a
// silent empty schedule. Retained sampled runs show one such case in nine,
// not a predicted failure rate. Reducing spacing below a real transit could
// increase D-142 rejection; it could never waive captured-order qualification.
// A nonempty plan still needs the unchanged review of every adjacent pair from
// the earlier of last positive and first drop through sweep end. No retries.
func Plan(deadline int64, plannedAt map[string]string, samples []Sample, original []Send) map[string]any {
	samples = append([]Sample{}, samples...)
	original = append([]Send{}, original...)
	sort.Slice(samples, func(i, j int) bool { return samples[i].PacketID < samples[j].PacketID })
	sort.Slice(original, func(i, j int) bool { return original[i].At < original[j].At })
	latencies := make([]int64, 0, len(samples))
	var maxTransit int64
	for _, s := range samples {
		latencies = append(latencies, s.Latency)
		maxTransit = max(maxTransit, s.Transit)
	}
	slices.Sort(latencies)
	var lo, hi, median int64
	if len(latencies) > 0 {
		lo, hi, median = latencies[0], latencies[len(latencies)-1], latencies[len(latencies)/2]
	}
	// Include arrival-latency spread: a fast following packet can catch a slow
	// predecessor even when send spacing exceeds node transit. Round up 0.1ms.
	bound := max(int64(500000), hi-lo+2*maxTransit+100000)
	spacing := ((bound + 99999) / 100000) * 100000
	margin := hi - lo + 3*spacing
	anchor := deadline - 100000000
	first := anchor - ((margin+1000000+spacing-1)/spacing)*spacing
	last := deadline + 100000000 + margin
	gaps := []int64{}
	for i := 1; i < len(original); i++ {
		gaps = append(gaps, original[i].At-original[i-1].At)
	}
	slices.Sort(gaps)
	gapStrings := []string{}
	for _, g := range slices.Compact(gaps) {
		gapStrings = append(gapStrings, fmt.Sprint(g))
	}
	added := []string{}
	candidates := []Candidate{}
	if len(samples) >= 20 {
		for predicted := first; predicted <= last; predicted += spacing {
			c := Candidate{At: predicted - median, ExcludedBy: []Send{}}
			for _, old := range original {
				delta := old.At - c.At
				if delta > -spacing && delta < spacing {
					c.ExcludedBy = append(c.ExcludedBy, old)
				}
			}
			candidates = append(candidates, c)
			if len(c.ExcludedBy) == 0 {
				added = append(added, fmt.Sprint(c.At))
			}
		}
	}
	reason := ""
	if len(samples) < 20 {
		reason = "same-run latency calibration unavailable: fewer than 20 samples"
	} else if len(added) == 0 {
		reason = "empty added schedule: every candidate excluded by original cadence sends"
	}
	return map[string]any{
		"planned_at": plannedAt, "deadline_mono_ns": fmt.Sprint(deadline), "qualified": len(added) > 0,
		"unqualified_reason": reason,
		"scope":              "D-140 added schedule only; same-run original-cadence capture-read latency, not exact kernel timestamps",
		"samples":            samples, "discounted_samples": []Sample{},
		"latency_min_ns": fmt.Sprint(lo), "latency_median_ns": fmt.Sprint(median), "latency_max_ns": fmt.Sprint(hi),
		"latency_spread_ns": fmt.Sprint(hi - lo), "max_transit_ns": fmt.Sprint(maxTransit), "spacing_ns": fmt.Sprint(spacing),
		"spacing_unrounded_ns": fmt.Sprint(bound), "cadence_gaps_ns": gapStrings,
		"cadence_gap_rule": "an interior candidate needs gap >= 2 * spacing; equality permits only the midpoint; actual grid exclusions listed for every candidate",
		"candidates":       candidates, "added_scheduled_mono_ns": added,
		"predicted_first_ingress_ns": fmt.Sprint(first), "predicted_last_ingress_ns": fmt.Sprint(last),
		"grid_anchor_offset_ns":                         "-100000000",
		"decision_tradeoff":                             "one whole-node boundary; spacing protects observed-range separation but cannot guarantee a sample in a roughly 3ms positive window; original D-101ms send remains; every attempt counts",
		"original_boundary_predicted_ingress_offset_ns": fmt.Sprint(-101000000 + median),
		"spacing_reason":                                "max(0.5ms, measured latency spread + twice measured maximum transit + 0.1ms), rounded up to 0.1ms; avoid existing cadence sends within one spacing; verify actual ingress/egress order",
	}
}

package boundaryplan

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"testing"
)

const history = "../../../../../docs/e2e/at/isolation/history"

func TestAT13_F24_01PlannerReplay(t *testing.T) {
	for _, tc := range []struct {
		name, dir string
		spacing   string
		count     int
	}{
		{"df9dbad7", "follow-up-24-run", "33200000", 0},
		{"328ab9e0", "follow-up-23-run", "6100000", 31},
		{"runner-1104", "follow-up-25-runner-replay", "4000000", 49},
	} {
		t.Run(tc.name, func(t *testing.T) {
			read := func(name string, value any) {
				t.Helper()
				raw, err := os.ReadFile(filepath.Join(history, tc.dir, name))
				if err != nil {
					t.Fatal(err)
				}
				if err := json.Unmarshal(raw, value); err != nil {
					t.Fatal(err)
				}
			}
			var old struct {
				Deadline int64             `json:"deadline_mono_ns,string"`
				Planned  map[string]string `json:"planned_at"`
				Samples  []Sample          `json:"samples"`
				Added    []string          `json:"added_scheduled_mono_ns"`
			}
			read("boundary-schedule.json", &old)
			var capture []struct {
				ID        int    `json:"packet_id"`
				Interface string `json:"interface"`
				Read      struct {
					Mono int64 `json:"mono_ns,string"`
				} `json:"capture_read"`
			}
			read("boundary-calibration-packets.json", &capture)
			// Verify replay inputs really are the checkpoint's captured samples.
			for _, sample := range old.Samples {
				seen := map[string]int64{}
				for _, row := range capture {
					if row.ID == sample.PacketID && seen[row.Interface] == 0 {
						seen[row.Interface] = row.Read.Mono
					}
				}
				if seen["fvmb0"] != sample.Ingress || seen["fvup0"] != sample.Egress || sample.Latency != sample.Ingress-sample.Send || sample.Transit != sample.Egress-sample.Ingress {
					t.Fatal("calibration input differs", sample)
				}
			}
			var verdict struct {
				Packets []struct {
					Probe Send `json:"probe"`
				} `json:"packets"`
			}
			read("deadline-verdict.json", &verdict)
			original := []Send{}
			for _, row := range verdict.Packets {
				if row.Probe.Phase != "dense_boundary" && row.Probe.At > old.Deadline-1000000000 {
					original = append(original, row.Probe)
				}
			}
			p := Plan(old.Deadline, old.Planned, old.Samples, original)
			added := p["added_scheduled_mono_ns"].([]string)
			if p["qualified"] != (tc.count > 0) || p["spacing_ns"] != tc.spacing || len(added) != tc.count {
				t.Fatalf("wrong plan: %+v", p)
			}
			if tc.count > 0 {
				before, _ := json.Marshal(old.Added)
				after, _ := json.Marshal(added)
				if !bytes.Equal(before, after) {
					t.Fatal("added schedule bytes changed")
				}
				t.Logf("added schedule JSON bytes identical; spacing=%s count=%d; diagnostic fields added", tc.spacing, tc.count)
			} else {
				if len(p["candidates"].([]Candidate)) != 14 || p["unqualified_reason"] != "empty added schedule: every candidate excluded by original cadence sends" {
					t.Fatal("empty schedule not explained")
				}
				for _, c := range p["candidates"].([]Candidate) {
					if len(c.ExcludedBy) == 0 {
						t.Fatal("missing exclusion", c)
					}
				}
				t.Log("F24-01: qualified=false; added=[]; 14 candidates with all excluding original sends; no discounts")
			}
			// Every retained candidate obeys the same exclusion and separation rule.
			spacing, _ := strconv.ParseInt(tc.spacing, 10, 64)
			for i, a := range added {
				at, _ := strconv.ParseInt(a, 10, 64)
				for _, old := range original {
					if delta := old.At - at; delta > -spacing && delta < spacing {
						t.Fatal("original cadence collision")
					}
				}
				if i > 0 {
					prev, _ := strconv.ParseInt(added[i-1], 10, 64)
					if at-prev < spacing {
						t.Fatal("dense probes too close")
					}
				}
			}
			if !reflect.DeepEqual(p["cadence_gaps_ns"], []string{"37000000", "63000000"}) {
				t.Fatal("cadence gaps missing")
			}
			if dir := os.Getenv("FVPN_AT_BOUNDARY_REPLAY_DIR"); dir != "" {
				raw, err := json.MarshalIndent(p, "", "  ")
				if err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(filepath.Join(dir, tc.name+"-plan.json"), append(raw, '\n'), 0600); err != nil {
					t.Fatal(err)
				}
			}
		})
	}
}

func TestAT13_F24_01MissingCalibration(t *testing.T) {
	p := Plan(10_000_000_000, map[string]string{"mono_ns": "9000000000", "wall": "2026-11-04T00:00:00Z"}, nil, nil)
	raw, err := json.Marshal(p)
	if err != nil || bytes.Contains(raw, []byte(":null")) || p["qualified"] != false || p["unqualified_reason"] != "same-run latency calibration unavailable: fewer than 20 samples" {
		t.Fatalf("missing calibration must be explicit: %s %v", raw, err)
	}
}

func TestD098_Followup24AndRunnerReplayPins(t *testing.T) {
	for _, dir := range []string{"follow-up-24", "follow-up-25-runner-replay"} {
		raw, err := os.ReadFile(filepath.Join(history, dir, "archive.json"))
		if err != nil {
			t.Fatal(err)
		}
		var manifest struct {
			Files []struct{ Path, SHA256 string }
		}
		if err := json.Unmarshal(raw, &manifest); err != nil {
			t.Fatal(err)
		}
		want := 213
		if dir == "follow-up-25-runner-replay" {
			want = 6
		}
		if len(manifest.Files) != want {
			t.Fatal("archive scope changed")
		}
		for _, file := range manifest.Files {
			raw, err := os.ReadFile(filepath.Join(history, dir, file.Path))
			if err != nil {
				t.Fatal(err)
			}
			hash := sha256.Sum256(raw)
			if hex.EncodeToString(hash[:]) != file.SHA256 {
				t.Fatal("archive changed", file.Path)
			}
		}
	}
}

//go:build ignore

package main

// TEST ONLY transparent mTLS receiver. Bodies are retained only for observations
// and lease renewal; authentication headers and credential responses are excluded.
import (
	"bufio"
	"bytes"
	"context"
	"crypto/tls"
	"crypto/x509"
	"database/sql"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"github.com/TED-H-com/Freedom-VPN/tests/e2e/at/isolation/boundaryplan"
	"golang.org/x/sys/unix"
	"io"
	_ "modernc.org/sqlite"
	"net"
	"net/http"
	"net/http/httputil"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

func observeProxy() {
	roots := func(path string) *x509.CertPool {
		raw, e := os.ReadFile(path)
		must(e)
		p := x509.NewCertPool()
		if !p.AppendCertsFromPEM(raw) {
			os.Exit(1)
		}
		return p
	}
	cert, e := tls.LoadX509KeyPair("/var/lib/vpn-node/identity/cert.pem", "/var/lib/vpn-node/identity/key.pem")
	must(e)
	target, _ := url.Parse("https://127.0.0.1:9444")
	proxy := httputil.NewSingleHostReverseProxy(target)
	proxy.Transport = &http.Transport{TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS12, RootCAs: roots("/etc/vpn-node/ca.pem"), Certificates: []tls.Certificate{cert}}, ResponseHeaderTimeout: 15 * time.Second}
	file, e := os.OpenFile("/var/lib/vpn-node/e2e/isolation-observations.jsonl", os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	must(e)
	defer file.Close()
	var mu sync.Mutex
	var queue []map[string]any
	go func() {
		for range time.NewTicker(100 * time.Millisecond).C {
			mu.Lock()
			batch := queue
			queue = nil
			mu.Unlock()
			for _, row := range batch {
				_ = json.NewEncoder(file).Encode(row)
			}
			_ = file.Sync()
		}
	}()
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !((r.Method == "POST" && (r.URL.Path == "/api/v1/agent/observations" || strings.Contains(r.URL.Path, "lease"))) || (r.Method == "GET" && strings.Contains(r.URL.Path, "desired-state"))) {
			proxy.ServeHTTP(w, r)
			return
		}
		raw, err := io.ReadAll(io.LimitReader(r.Body, 2<<20))
		if err != nil {
			http.Error(w, "capture read failed", 500)
			return
		}
		r.Body.Close()
		r.Body = io.NopCloser(bytes.NewReader(raw))
		row := map[string]any{"received_at": time.Now().UTC().Format(time.RFC3339Nano), "path": r.URL.Path}
		if json.Valid(raw) {
			row["body"] = json.RawMessage(raw)
		}
		capture := &captureResponse{ResponseWriter: w}
		proxy.ServeHTTP(capture, r)
		row["response_at"] = time.Now().UTC().Format(time.RFC3339Nano)
		row["status"] = capture.status
		if json.Valid(capture.body.Bytes()) {
			row["response"] = json.RawMessage(capture.body.Bytes())
		}
		mu.Lock()
		queue = append(queue, row)
		mu.Unlock()
	})
	srv := &http.Server{Addr: "127.0.0.1:9445", Handler: handler, ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 30 * time.Second, WriteTimeout: 30 * time.Second, TLSConfig: &tls.Config{MinVersion: tls.VersionTLS12, ClientCAs: roots("/etc/vpn-node/agent-ca.pem"), ClientAuth: tls.RequireAndVerifyClientCert}}
	must(srv.ListenAndServeTLS("/etc/vpn-node/fault-proxy.crt", "/etc/vpn-node/fault-proxy.key"))
}

type captureResponse struct {
	http.ResponseWriter
	status int
	body   bytes.Buffer
}

func (w *captureResponse) WriteHeader(code int) { w.status = code; w.ResponseWriter.WriteHeader(code) }
func (w *captureResponse) Write(b []byte) (int, error) {
	if w.status == 0 {
		w.WriteHeader(200)
	}
	w.body.Write(b)
	return w.ResponseWriter.Write(b)
}

func configureObservation() {
	p := "/etc/vpn-node/agent-run.json"
	raw, e := os.ReadFile(p)
	must(e)
	var cfg map[string]any
	must(json.Unmarshal(raw, &cfg))
	for _, k := range []string{"heartbeat_seconds", "poll_seconds", "observation_seconds"} {
		cfg[k] = 1
	}
	// Agent-core 27's opt-in, detached producer timing; no product wire change.
	// Observe downstream of the unchanged devstack proxy, including its hold seam.
	cfg["control_url"] = "https://127.0.0.1:9445"
	cfg["test_timing_path"] = "/var/lib/vpn-node/e2e/isolation-operations.jsonl"
	if cfg["test_mode"] != true {
		panic("producer timing requires the existing TEST ONLY node")
	}
	raw, e = json.MarshalIndent(cfg, "", "  ")
	must(e)
	must(os.WriteFile(p, raw, 0600))
	raw, e = json.Marshal(clockIdentity())
	must(e)
	must(os.WriteFile("/var/lib/vpn-node/e2e/isolation-clock.json", raw, 0600))
}

func clockIdentity() map[string]string {
	boot, e := os.ReadFile("/proc/sys/kernel/random/boot_id")
	must(e)
	offsets, e := os.ReadFile("/proc/self/timens_offsets")
	must(e)
	namespace, e := os.Readlink("/proc/self/ns/time")
	must(e)
	return map[string]string{"boot_id": strings.TrimSpace(string(boot)), "time_namespace": namespace, "offsets": string(offsets), "clock": "CLOCK_MONOTONIC"}
}

// Read the live agent's clock namespace after an ordinary container restart.
func producerClock() {
	row := clockIdentity()
	row["sample_start"] = time.Now().UTC().Format(time.RFC3339Nano)
	raw, e := exec.Command("pgrep", "-x", "fvpn-agent").Output()
	must(e)
	pid := strings.TrimSpace(string(raw))
	_, e = strconv.Atoi(pid)
	must(e)
	row["agent_pid"] = pid
	row["time_namespace"], e = os.Readlink("/proc/" + pid + "/ns/time")
	must(e)
	for name, file := range map[string]string{"offsets": "timens_offsets", "process_stat": "stat"} {
		raw, e = os.ReadFile("/proc/" + pid + "/" + file)
		must(e)
		row[name] = strings.TrimSpace(string(raw))
	}
	raw, e = os.ReadFile("/var/lib/vpn-node/e2e/isolation-operations.jsonl")
	must(e)
	lines := bytes.Split(bytes.TrimSpace(raw), []byte("\n"))
	var last map[string]any
	must(json.Unmarshal(lines[len(lines)-1], &last))
	row["measurement_run_id"], _ = last["run_id"].(string)
	row["latest_sequence"], _ = last["sequence"].(string)
	row["scope"] = "Read-only live source agent clock after ordinary container restart; no clock or namespace mutation."
	row["sample_end"] = time.Now().UTC().Format(time.RFC3339Nano)
	must(json.NewEncoder(os.Stdout).Encode(row))
}

// All timestamps use the host CLOCK_MONOTONIC shared by these containers.
func monoNS() int64 {
	var ts unix.Timespec
	must(unix.ClockGettime(unix.CLOCK_MONOTONIC, &ts))
	return ts.Nano()
}
func clockSample() map[string]string {
	return map[string]string{"mono_ns": strconv.FormatInt(monoNS(), 10), "wall": time.Now().UTC().Format(time.RFC3339Nano)}
}
func deadlineProbes() {
	identity := clockIdentity()
	deadline, e := strconv.ParseInt(os.Args[3], 10, 64)
	must(e)
	f, e := os.Create(os.Args[4])
	must(e)
	defer f.Close()
	// The main cadence is phased at D-(100ms+1ms). A second cadence has
	// an arbitrary 37ms offset and shares the explicit D-101ms boundary sample.
	type scheduled struct {
		at    int64
		phase string
	}
	var schedule []scheduled
	firstN, lastN := int64(-80), int64(20)
	if os.Args[1] == "renewal-probes" {
		deadline = monoNS() + 70000000000
		firstN, lastN = -698, -1
	}
	for n := firstN; n <= lastN; n++ {
		schedule = append(schedule, scheduled{deadline - 101000000 + n*100000000, "phased"})
		schedule = append(schedule, scheduled{deadline - 64000000 + n*100000000, "arbitrary_37ms"})
	}
	// D-140: one planning checkpoint after the original cadence has supplied
	// latency samples. It is not a packet and changes neither original cadence.
	if os.Args[1] == "deadline-probes" {
		schedule = append(schedule, scheduled{deadline - 1000000000, "plan_dense"})
	}
	sort.Slice(schedule, func(i, j int) bool { return schedule[i].at < schedule[j].at })
	var sent = map[int]int64{}
	var wg sync.WaitGroup
	var mu sync.Mutex
	id := 0
	for index := 0; index < len(schedule); index++ {
		s := schedule[index]
		if s.phase == "dense_boundary" {
			// Avoid timer coalescing at sub-millisecond spacing. This affects only
			// added probes; send/read behavior and both old cadences stay intact.
			if delay := s.at - monoNS() - 1500000; delay > 0 {
				time.Sleep(time.Duration(delay))
			}
			for monoNS() < s.at {
				runtime.Gosched()
			}
		} else if delay := s.at - monoNS(); delay > 0 {
			time.Sleep(time.Duration(delay))
		}
		if s.phase == "plan_dense" {
			plannedAt := clockSample()
			var captures []map[string]any
			if len(os.Args) > 5 {
				raw, err := os.ReadFile(os.Args[5])
				if err == nil {
					for _, line := range bytes.Split(raw, []byte("\n")) {
						var row map[string]any
						if json.Unmarshal(line, &row) == nil {
							captures = append(captures, row)
						}
					}
				}
			}
			ingress, egress := map[int]int64{}, map[int]int64{}
			for _, r := range captures {
				n, _ := r["packet_id"].(float64)
				stamp, _ := r["capture_read"].(map[string]any)
				v, _ := stamp["mono_ns"].(string)
				at, _ := strconv.ParseInt(v, 10, 64)
				if r["interface"] == "fvmb0" && ingress[int(n)] == 0 {
					ingress[int(n)] = at
				}
				if r["interface"] == "fvup0" && egress[int(n)] == 0 {
					egress[int(n)] = at
				}
			}
			samples := []boundaryplan.Sample{}
			mu.Lock()
			for n, in := range ingress {
				out, send := egress[n], sent[n]
				if send <= 0 || in < send || out < in {
					continue
				}
				samples = append(samples, boundaryplan.Sample{PacketID: n, Send: send, Ingress: in, Egress: out, Latency: in - send, Transit: out - in})
			}
			mu.Unlock()
			original := []boundaryplan.Send{}
			for _, old := range schedule[index+1:] {
				original = append(original, boundaryplan.Send{At: old.at, Phase: old.phase})
			}
			plan := boundaryplan.Plan(deadline, plannedAt, samples, original)
			for _, at := range plan["added_scheduled_mono_ns"].([]string) {
				n, err := strconv.ParseInt(at, 10, 64)
				must(err)
				schedule = append(schedule, scheduled{n, "dense_boundary"})
			}
			sort.Slice(schedule[index+1:], func(i, j int) bool { return schedule[index+1+i].at < schedule[index+1+j].at })
			raw, err := json.MarshalIndent(plan, "", "  ")
			must(err)
			must(os.WriteFile(os.Args[4]+".schedule.json", append(raw, '\n'), 0600))
			continue
		}
		id++
		wg.Add(1)
		go func(id int, s scheduled) {
			defer wg.Done()
			port := 42000 + id
			dst := &net.UDPAddr{IP: net.ParseIP(os.Args[2]), Port: 8080}
			c, e := net.DialUDP("udp4", &net.UDPAddr{Port: port}, dst)
			row := map[string]any{"trace_clock": identity, "packet_id": id, "source_port": port, "phase": s.phase, "scheduled_mono_ns": fmt.Sprint(s.at), "deadline_mono_ns": fmt.Sprint(deadline), "send": clockSample()}
			mu.Lock()
			sent[id], _ = strconv.ParseInt(row["send"].(map[string]string)["mono_ns"], 10, 64)
			mu.Unlock()
			result := "socket_error"
			if e == nil {
				defer c.Close()
				_ = c.SetDeadline(time.Now().Add(80 * time.Millisecond))
				_, e = c.Write([]byte("TEST ONLY"))
				if e == nil {
					b := make([]byte, 9)
					n, err := c.Read(b)
					result = "timeout"
					if err == nil && n == 9 && string(b) == "TEST ONLY" {
						result = "ok"
					}
				} else {
					result = "send_error"
				}
			}
			row["read_completion"] = clockSample()
			row["result"] = result
			mu.Lock()
			_ = json.NewEncoder(f).Encode(row)
			mu.Unlock()
		}(id, s)
	}
	wg.Wait()
}
func packetClock() {
	seconds, e := strconv.Atoi(os.Args[2])
	must(e)
	f, e := os.Create(os.Args[3])
	must(e)
	defer f.Close()
	// SOCK_DGRAM strips link headers on both WireGuard and Ethernet. Retain
	// only UDP headers for TEST ONLY source-port packet IDs, never payload.
	fd, e := unix.Socket(unix.AF_PACKET, unix.SOCK_DGRAM|unix.SOCK_NONBLOCK, int(0x0300))
	must(e)
	defer unix.Close(fd)
	ifaces, e := net.Interfaces()
	must(e)
	names := map[int]string{}
	for _, it := range ifaces {
		names[it.Index] = it.Name
	}
	_ = json.NewEncoder(f).Encode(map[string]any{"event": "ready", "clock": clockSample(), "trace_clock": clockIdentity()})
	end := monoNS() + int64(seconds)*1000000000
	b := make([]byte, 65536)
	for monoNS() < end {
		n, sa, e := unix.Recvfrom(fd, b, 0)
		stamp := clockSample()
		if e == unix.EAGAIN {
			time.Sleep(200 * time.Microsecond)
			continue
		}
		if e != nil {
			must(e)
		}
		link, ok := sa.(*unix.SockaddrLinklayer)
		if !ok || n < 28 || b[0]>>4 != 4 || b[9] != 17 {
			continue
		}
		ihl := int(b[0]&15) * 4
		if ihl < 20 || n < ihl+8 {
			continue
		}
		src, dst := int(binary.BigEndian.Uint16(b[ihl:])), int(binary.BigEndian.Uint16(b[ihl+2:]))
		id := src - 42000
		if dst != 8080 || id < 1 || id > 2000 {
			continue
		}
		name := names[link.Ifindex]
		if name != "fvmb0" && name != "fvup0" {
			continue
		}
		_ = json.NewEncoder(f).Encode(map[string]any{"packet_id": id, "interface": name, "packet_type": link.Pkttype, "capture_read": stamp, "source_port": src, "destination_port": dst})
	}
	stats, e := unix.GetsockoptTpacketStats(fd, unix.SOL_PACKET, unix.PACKET_STATISTICS)
	row := map[string]any{"event": "complete", "clock": clockSample(), "statistics_available": e == nil}
	if e == nil {
		row["packets"] = stats.Packets
		row["drops"] = stats.Drops
	}
	_ = json.NewEncoder(f).Encode(row)
}

// Passive netlink monitor: timestamps are userspace receipt bounds, never
// mislabelled as renderer start or command completion.
func nftClock() {
	f, e := os.OpenFile("/var/lib/vpn-node/e2e/isolation-nft-events.jsonl", os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	must(e)
	defer f.Close()
	ctx, cancel := context.WithTimeout(context.Background(), 45*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "nft", "-j", "monitor")
	pipe, e := cmd.StdoutPipe()
	must(e)
	must(cmd.Start())
	scanner := bufio.NewScanner(pipe)
	scanner.Buffer(make([]byte, 65536), 8<<20)
	for scanner.Scan() {
		at := clockSample()
		line := scanner.Bytes()
		var doc map[string]any
		if json.Unmarshal(line, &doc) != nil {
			continue
		}
		entries, _ := doc["nftables"].([]any)
		if len(entries) == 0 {
			entries = []any{doc}
		}
		for _, entry := range entries {
			actions, _ := entry.(map[string]any)
			for action, obj := range actions {
				kinds, _ := obj.(map[string]any)
				for kind, body := range kinds {
					b, _ := body.(map[string]any)
					if b["table"] != "fvpn" {
						continue
					}
					name, _ := b["name"].(string)
					chain, _ := b["chain"].(string)
					if name != "fv_deadline_guard" && name != "allowed_v4" && kind != "rule" {
						continue
					}
					row := map[string]any{"receipt": at, "action": action, "kind": kind, "name": name, "chain": chain}
					if comment, ok := b["comment"].(string); ok && strings.HasPrefix(comment, "fvpn_generation=") {
						row["generation_comment"] = comment
					}
					_ = json.NewEncoder(f).Encode(row)
				}
			}
		}
	}
	_ = cmd.Wait()
}

