// TEST ONLY terminal stop sample inside the lab. Preserve the supervisor pause
// contract, signal the exact process through pidfd, and observe its exit. The
// supervisor retains its 15-second policy. The matching parent wait receipt
// supplies exit status; elapsed time alone never establishes graceful exit.
func agentStopSample() {
	raw, err := os.ReadFile("/var/lib/vpn-node/e2e/agent.pid")
	must(err)
	pid, err := strconv.Atoi(strings.TrimSpace(string(raw)))
	must(err)
	fd, err := unix.PidfdOpen(pid, 0)
	must(err)
	defer unix.Close(fd)
	launchRaw, err := os.ReadFile("/var/lib/vpn-node/e2e/agent-process-id")
	must(err)
	launch := strings.TrimSpace(string(launchRaw))
	if launch == "" || launch == "." || filepath.Base(launch) != launch {
		panic("invalid launch ID")
	}
	stat, err := os.ReadFile(fmt.Sprintf("/proc/%d/stat", pid))
	must(err)
	fields := strings.Fields(string(stat)[strings.LastIndex(string(stat), ")")+1:])
	if len(fields) < 20 {
		panic("short process stat")
	}
	startTicks := fields[19]
	row := map[string]any{"pid": pid, "launch_id": launch, "start_ticks": startTicks, "agent_budget_seconds": 15, "scope": "TEST ONLY terminal stop; pidfd SIGTERM send and exit readiness brackets; supervisor pause and escalation retained", "step_cancel": "not observable here"}
	must(os.WriteFile("/var/lib/vpn-node/e2e/pause-agent", nil, 0600))
	start := monoNS()
	row["signal_start"] = clockSample()
	err = unix.PidfdSendSignal(fd, unix.SIGTERM, nil, 0)
	row["signal_return"] = clockSample()
	row["signal_ok"] = err == nil
	fds := []unix.PollFd{{Fd: int32(fd), Events: unix.POLLIN}}
	lastAlive := start
	exited := false
	for monoNS()-start < int64(15*time.Second) {
		n, e := unix.Poll(fds, 10)
		if e == unix.EINTR {
			continue
		}
		if e != nil {
			break
		}
		if n > 0 && fds[0].Revents&unix.POLLIN != 0 {
			exited = true
			break
		}
		lastAlive = monoNS()
	}
	end := monoNS()
	row["exit_observed"], row["exit_sample"] = exited, clockSample()
	row["signal_to_exit_upper_ns"], row["last_alive_since_signal_ns"] = strconv.FormatInt(end-start, 10), strconv.FormatInt(lastAlive-start, 10)
	row["within_15s"] = err == nil && exited && end-start <= int64(15*time.Second)
	cleanup, e := exec.Command("agent-service.sh", "stop").CombinedOutput()
	row["supervisor_stop_ok"], row["supervisor_stop_output"] = e == nil, strings.TrimSpace(string(cleanup))
	row["parent_wait_available"] = false
	for i := 0; i < 200; i++ {
		raw, e := os.ReadFile("/var/lib/vpn-node/e2e/agent-exits/" + launch + ".json")
		if e == nil {
			var receipt struct {
				ID         string `json:"id"`
				PID        int    `json:"pid"`
				StartTicks string `json:"start_ticks"`
				ExitCode   *int   `json:"exit_code"`
				Signal     *int   `json:"signal"`
			}
			if json.Unmarshal(raw, &receipt) == nil {
				matched := receipt.ID == launch && receipt.PID == pid && receipt.StartTicks == startTicks
				row["parent_wait_receipt"], row["parent_wait_available"], row["parent_identity_matched"] = json.RawMessage(raw), true, matched
				row["cooperative_exit"] = matched && receipt.Signal == nil && receipt.ExitCode != nil && *receipt.ExitCode == 0
				break
			}
		}
		time.Sleep(10 * time.Millisecond)
	}
	if raw, e := os.ReadFile("/var/lib/vpn-node/e2e/agent-exits/" + launch + ".sigkill.json"); e == nil && json.Valid(raw) {
		row["attempted_escalation"] = json.RawMessage(raw)
	}
	row["outcome_source"] = "parent wait receipt; escalation sidecar is intent only; pidfd timestamps bound observation, not exact kernel exit"
	must(json.NewEncoder(os.Stdout).Encode(row))
}

package isolation

import (
	"encoding/json"
	"fmt"
	"strconv"
)

type DeadlineVerdict struct {
	Passed             bool             `json:"passed"`
	Deadline           string           `json:"deadline_mono_ns"`
	LastPositive       string           `json:"last_positive_mono_ns"`
	FirstDrop          string           `json:"first_drop_mono_ns"`
	LastPositiveOffset string           `json:"last_positive_offset_ns"`
	FirstDropOffset    string           `json:"first_drop_offset_ns"`
	Positives          int              `json:"positives"`
	Drops              int              `json:"drops"`
	Errors             []string         `json:"errors"`
	Packets            []map[string]any `json:"packets"`
}

// EvaluateDeadline requires independent ingress and egress observations, complete
// zero-drop capture and every send/read. Missing evidence never proves denial.
func EvaluateDeadline(probes, capture []byte, deadline int64) DeadlineVerdict {
	v := DeadlineVerdict{Deadline: fmt.Sprint(deadline), Errors: []string{}, Packets: []map[string]any{}}
	var ps, cs []map[string]any
	if json.Unmarshal(probes, &ps) != nil || json.Unmarshal(capture, &cs) != nil || deadline <= 0 {
		v.Errors = append(v.Errors, "invalid trace")
		return v
	}
	stamp := func(row map[string]any, key string) int64 {
		m, _ := row[key].(map[string]any)
		s, _ := m["mono_ns"].(string)
		n, _ := strconv.ParseInt(s, 10, 64)
		return n
	}
	var complete bool
	ingress, egress := map[int]int64{}, map[int]int64{}
	for _, r := range cs {
		if r["event"] == "complete" {
			complete = r["statistics_available"] == true && r["drops"] == float64(0)
		}
		id, _ := r["packet_id"].(float64)
		at := stamp(r, "capture_read")
		switch r["interface"] {
		case "fvmb0":
			if ingress[int(id)] == 0 {
				ingress[int(id)] = at
			}
		case "fvup0":
			if egress[int(id)] == 0 {
				egress[int(id)] = at
			}
		}
	}
	if !complete {
		v.Errors = append(v.Errors, "capture incomplete or dropped packets")
	}
	var last, first int64
	for _, r := range ps {
		id, _ := r["packet_id"].(float64)
		in, out := ingress[int(id)], egress[int(id)]
		row := map[string]any{"probe": r, "ingress_mono_ns": fmt.Sprint(in), "egress_mono_ns": fmt.Sprint(out)}
		v.Packets = append(v.Packets, row)
		if in == 0 || stamp(r, "send") == 0 || stamp(r, "read_completion") == 0 {
			v.Errors = append(v.Errors, fmt.Sprintf("packet %d missing send/ingress/read", int(id)))
			continue
		}
		if out > 0 {
			v.Positives++
			if out > last {
				last = out
			}
			if out >= deadline {
				v.Errors = append(v.Errors, fmt.Sprintf("packet %d post-deadline egress", int(id)))
			}
		} else {
			v.Drops++
			if first == 0 || in < first {
				first = in
			}
			if r["result"] != "timeout" {
				v.Errors = append(v.Errors, fmt.Sprintf("packet %d no egress but result=%v", int(id), r["result"]))
			}
		}
	}
	v.LastPositive = fmt.Sprint(last)
	v.FirstDrop = fmt.Sprint(first)
	v.LastPositiveOffset = fmt.Sprint(last - deadline)
	v.FirstDropOffset = fmt.Sprint(first - deadline)
	if last == 0 || last < deadline-101000000 {
		v.Errors = append(v.Errors, "last positive earlier than D-101ms")
	}
	if first == 0 || first > deadline+100000000 {
		v.Errors = append(v.Errors, "first drop later than D+100ms")
	}
	if first != 0 && last >= first {
		v.Errors = append(v.Errors, "later positive after first drop")
	}
	v.Passed = len(v.Errors) == 0
	return v
}

