package e2e

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"net/url"
	"reflect"
	"strconv"
	"time"

	"github.com/google/uuid"
)

const (
	nodeWriteAttempts = 3
	nodeWriteTimeout  = 10 * time.Second
)

// These receipts deliberately exclude bodies, credentials and transport error
// text. A command accepted here still needs its caller's observed-state gates.
type nodeWriteRead struct {
	Method     string    `json:"method"`
	Path       string    `json:"path"`
	IfMatch    string    `json:"if_match"`
	BodySHA256 string    `json:"body_sha256"`
	StartedAt  time.Time `json:"started_at"`
	FinishedAt time.Time `json:"finished_at"`
	Status     int       `json:"status"`
	ErrorCode  string    `json:"error_code"`
	ETag       string    `json:"etag"`
	Transport  bool      `json:"transport_error"`
	Intended   bool      `json:"already_intended"`
}

type nodeWriteAttempt struct {
	Method         string         `json:"method"`
	Path           string         `json:"path"`
	IfMatch        string         `json:"if_match"`
	IdempotencyKey string         `json:"idempotency_key"`
	BodySHA256     string         `json:"body_sha256"`
	StartedAt      time.Time      `json:"started_at"`
	FinishedAt     time.Time      `json:"finished_at"`
	Status         int            `json:"status"`
	ErrorCode      string         `json:"error_code"`
	CurrentVersion string         `json:"current_resource_version,omitempty"`
	Transport      bool           `json:"transport_error"`
	Reread         *nodeWriteRead `json:"reread,omitempty"`
}

type nodeWriteTrace struct {
	StartedAt    time.Time          `json:"started_at"`
	FinishedAt   time.Time          `json:"finished_at"`
	MaxAttempts  int                `json:"max_attempts"`
	LimitSeconds int                `json:"limit_seconds"`
	Status       Status             `json:"status"`
	Outcome      string             `json:"outcome"`
	Attempts     []nodeWriteAttempt `json:"attempts"`
}

type nodeWriteResult struct {
	Reply           reply
	Err             error
	AlreadyIntended bool
	Receipt         nodeWriteTrace
}

// Accepted reports command acceptance, not operation or observed-state completion.
func (r nodeWriteResult) Accepted(statuses ...int) bool { return r.accepted(statuses...) }

func (r nodeWriteResult) accepted(statuses ...int) bool {
	if r.Err != nil {
		return false
	}
	if r.AlreadyIntended {
		return true
	}
	for _, status := range statuses {
		if r.Reply.Status == status {
			return true
		}
	}
	return false
}

// writeNode follows §14.5 only for an exact RESOURCE_VERSION_CONFLICT. The
// caller supplies the initial GET's ETag and the desired-field predicate. A
// failed write's transaction (including its key reservation) is rolled back by
// httpapi.Commands; the body hash excludes If-Match. Keep one key and body for
// this logical command. No other response or transport failure is retried.
func (s *httpSession) writeNode(ctx context.Context, method, writeURL, readURL string, body any, etag string, intended func([]byte) bool, success []int, note func(string, string)) (out nodeWriteResult) {
	trace := nodeWriteTrace{StartedAt: time.Now().UTC(), MaxAttempts: nodeWriteAttempts, LimitSeconds: int(nodeWriteTimeout / time.Second), Status: StatusBlocked}
	defer func() {
		trace.FinishedAt = time.Now().UTC()
		out.Receipt = trace
		raw, _ := json.Marshal(trace)
		note("node_write", string(raw))
	}()
	bounded, cancel := context.WithTimeout(ctx, nodeWriteTimeout)
	defer cancel()
	// net/http can silently replay keyed requests on a reused connection, and
	// Client normally follows redirects. Neither is an allowed extra attempt.
	// Use private HTTP/1 connections for this command only, preserving the lab
	// dial/TLS settings, cookies and CSRF. Other callers retain their client.
	base := s.http.Transport
	if base == nil {
		base = http.DefaultTransport
	}
	transport, ok := base.(*http.Transport)
	if !ok {
		out.Err, trace.Outcome = errors.New("node write requires an HTTP transport"), "unsupported_transport"
		return
	}
	private := transport.Clone()
	private.DisableKeepAlives = true
	private.Protocols = new(http.Protocols)
	private.Protocols.SetHTTP1(true)
	defer private.CloseIdleConnections()
	client := *s.http
	client.Transport = private
	client.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	once := &httpSession{http: &client, csrf: s.csrf}
	key := uuid.NewString()
	for attempt := 0; attempt < nodeWriteAttempts; attempt++ {
		if bounded.Err() != nil {
			out.Err, trace.Outcome = bounded.Err(), "time_limit"
			return
		}
		row := nodeWriteAttempt{Method: method, Path: evidencePath(writeURL), IfMatch: etag, IdempotencyKey: key, StartedAt: time.Now().UTC()}
		out.Reply, out.Err = once.callObserved(bounded, method, writeURL, body, map[string]string{"If-Match": etag, "Idempotency-Key": key}, func(payload []byte) {
			digest := sha256.Sum256(payload)
			row.BodySHA256 = hex.EncodeToString(digest[:])
		})
		row.FinishedAt, row.Status, row.ErrorCode = time.Now().UTC(), out.Reply.Status, out.Reply.Code
		row.Transport = out.Err != nil
		var env struct {
			Error struct {
				Details struct {
					Version string `json:"current_resource_version"`
				} `json:"details"`
			} `json:"error"`
		}
		if json.Unmarshal(out.Reply.Body, &env) == nil && decimalVersion(env.Error.Details.Version) {
			row.CurrentVersion = env.Error.Details.Version
		}
		trace.Attempts = append(trace.Attempts, row)
		if out.Err != nil {
			trace.Outcome = "transport_error"
			if bounded.Err() != nil {
				trace.Outcome = "time_limit"
			}
			return
		}
		if out.Reply.Status != 412 || out.Reply.Code != "RESOURCE_VERSION_CONFLICT" {
			trace.Outcome = "non_conflict_response"
			if out.accepted(success...) {
				trace.Status, trace.Outcome = StatusPass, "accepted"
			}
			return
		}
		if bounded.Err() != nil {
			out.Err, trace.Outcome = bounded.Err(), "time_limit"
			return
		}
		emptyDigest := sha256.Sum256(nil)
		read := &nodeWriteRead{Method: "GET", Path: evidencePath(readURL), BodySHA256: hex.EncodeToString(emptyDigest[:]), StartedAt: time.Now().UTC()}
		got, err := once.call(bounded, "GET", readURL, nil, nil)
		read.FinishedAt, read.Status, read.ErrorCode, read.ETag, read.Transport = time.Now().UTC(), got.Status, got.Code, got.Header.Get("ETag"), err != nil
		trace.Attempts[len(trace.Attempts)-1].Reread = read
		if err != nil || got.Status != 200 {
			out.Err, trace.Outcome = err, "reread_failed"
			if bounded.Err() != nil {
				trace.Outcome = "time_limit"
			}
			return
		}
		read.Intended = intended(got.Body)
		if read.Intended {
			out.AlreadyIntended = true
			trace.Status, trace.Outcome = StatusPass, "already_intended"
			return
		}
		etag = read.ETag
		if len(etag) < 3 || etag[0] != '"' || etag[len(etag)-1] != '"' || !decimalVersion(etag[1:len(etag)-1]) {
			trace.Outcome = "invalid_reread_etag"
			return
		}
	}
	trace.Outcome = "attempt_limit"
	return
}

func evidencePath(raw string) string {
	u, err := url.Parse(raw)
	if err != nil {
		return "invalid_path"
	}
	return u.Path
}

func decimalVersion(s string) bool {
	v, err := strconv.ParseUint(s, 10, 64)
	return err == nil && strconv.FormatUint(v, 10) == s
}

// nodeFieldsMatch compares only the requested desired fields. UseNumber keeps
// rates/versions exact; missing/null fields never count as a matching object.
func nodeFieldsMatch(want any) func([]byte) bool {
	raw, err := json.Marshal(want)
	var expected map[string]any
	if err == nil {
		d := json.NewDecoder(bytes.NewReader(raw))
		d.UseNumber()
		err = d.Decode(&expected)
	}
	return func(body []byte) bool {
		if err != nil || len(expected) == 0 {
			return false
		}
		var actual map[string]any
		d := json.NewDecoder(bytes.NewReader(body))
		d.UseNumber()
		if d.Decode(&actual) != nil {
			return false
		}
		for key, value := range expected {
			if !reflect.DeepEqual(actual[key], value) {
				return false
			}
		}
		return true
	}
}

func revokedNode(body []byte) bool {
	return nodeFieldsMatch(map[string]string{"lifecycle_state": "revoked"})(body)
}

func publishedNode(group uuid.UUID) func([]byte) bool {
	// The publisher requests exactly one group, so array order is immaterial.
	return nodeFieldsMatch(map[string]any{"publication_intent": "published", "group_ids": []string{group.String()}})
}

//go:build e2e

package e2e

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

// StartSecondExit creates one more real node and its independent resolver,
// identity/state directories and durable network namespace on the existing lab
// bridges. Call after PrepareServingBaseline, then EnrollAt(..., "node2").
// It does not publish the exit or infer serviceability. e2e-down removes it.
func (s *Stack) StartSecondExit(ctx context.Context) error { return s.startSecondExit(ctx, false) }
func (s *Stack) startSecondExit(ctx context.Context, clone bool) error {
	slot, octet := "node2", ".22"
	if clone {
		slot, octet = "node-clone", ".23"
	}
	return s.startExitSlot(ctx, slot, octet, clone, false)
}
func (s *Stack) startExitSlot(ctx context.Context, slot, lastOctet string, clone, hold bool) error {
	base := filepath.Join(s.lab.state, slot)
	if err := os.Mkdir(base, 0700); err != nil {
		return fmt.Errorf("second node requires a fresh slot: %w", err)
	}
	for _, dir := range []string{"etc", "var/e2e", "adguard/conf", "adguard/work", "netbird", "opt"} {
		if err := os.MkdirAll(filepath.Join(base, dir), 0700); err != nil {
			return err
		}
	}
	if hold {
		if err := os.WriteFile(filepath.Join(base, "var/e2e/hold-enrolling"), nil, 0600); err != nil {
			return err
		}
	}
	run := func(args ...string) error {
		if err := exec.CommandContext(ctx, "docker", args...).Run(); err != nil {
			return fmt.Errorf("second node Docker step failed: %w", err)
		}
		return nil
	}
	if clone {
		if err := run("stop", "-t", "25", s.lab.node); err != nil {
			return err
		}
		defer func() {
			resume, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
			defer cancel()
			_ = exec.CommandContext(resume, "docker", "start", s.lab.node).Run()
		}()
	}
	if err := run("cp", s.lab.node+":/etc/vpn-node/.", filepath.Join(base, "etc")); err != nil {
		return err
	}
	// Clean second exits copy configuration/public trust; the explicit fault
	// fixture below also snapshots durable identity while the source is stopped.
	// The entrypoint reads this kernel's boot id and rebuilds recovery config.
	for _, file := range []string{"boot-id", "updater-recover.json"} {
		_ = os.Remove(filepath.Join(base, "etc", file))
	}
	if !clone {
		_ = os.Remove(filepath.Join(base, "etc", "machine-id"))
	}
	prefix := s.lab.originIP[:strings.LastIndex(s.lab.originIP, ".")]
	for _, file := range []string{"agent-enroll.json", "agent-run.json"} {
		path := filepath.Join(base, "etc", file)
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var cfg map[string]any
		if err = json.Unmarshal(raw, &cfg); err != nil {
			return err
		}
		dp, ok := cfg["datapath"].(map[string]any)
		if !ok {
			return fmt.Errorf("datapath missing")
		}
		dp["snat"] = prefix + lastOctet
		raw, err = json.MarshalIndent(cfg, "", "  ")
		if err != nil {
			return err
		}
		if err = os.WriteFile(path, raw, 0600); err != nil {
			return err
		}
	}
	if err := run("cp", s.lab.prefix+"-adguard:/opt/adguardhome/conf/AdGuardHome.yaml", filepath.Join(base, "adguard/conf/AdGuardHome.yaml")); err != nil {
		return err
	}
	image, err := exec.CommandContext(ctx, "docker", "inspect", "--format={{.Image}}", s.lab.node).Output()
	if err != nil {
		return err
	}
	dnsImage, err := exec.CommandContext(ctx, "docker", "inspect", "--format={{.Image}}", s.lab.prefix+"-adguard").Output()
	if err != nil {
		return err
	}
	name := s.lab.prefix + "-" + slot
	ns := name + "-netns"
	if err = run("run", "-d", "--name", ns, "--hostname", name, "--network", s.lab.prefix, "--entrypoint", "sleep", strings.TrimSpace(string(image)), "infinity"); err != nil {
		return err
	}
	if err = run("network", "connect", "--ip", prefix+lastOctet, s.lab.prefix+"-origin", ns); err != nil {
		return err
	}
	if err = run("run", "-d", "--name", name+"-adguard", "--network", "container:"+ns, "--mount", "type=bind,src="+filepath.Join(base, "adguard/conf")+",dst=/opt/adguardhome/conf", "--mount", "type=bind,src="+filepath.Join(base, "adguard/work")+",dst=/opt/adguardhome/work", strings.TrimSpace(string(dnsImage)), "--no-check-update", "--no-permcheck", "-c", "/opt/adguardhome/conf/AdGuardHome.yaml", "-w", "/opt/adguardhome/work"); err != nil {
		return err
	}
	if clone {
		// Source is stopped and target has not booted. Pipe archives directly into
		// the private target mounts; never print/store an archive in evidence.
		// The client stores its X25519 identity in /var/lib/netbird, not /etc/netbird.
		for _, copy := range []struct{ source, target string }{{"/var/lib/vpn-node/.", "var"}, {"/var/lib/netbird/.", "netbird"}, {"/opt/vpn-node/.", "opt"}} {
			read := exec.CommandContext(ctx, "docker", "cp", s.lab.node+":"+copy.source, "-")
			write := exec.CommandContext(ctx, "docker", "run", "--rm", "-i", "--name", name+"-copy", "--network", "none", "--mount", "type=bind,src="+filepath.Join(base, copy.target)+",dst=/copy", "--entrypoint", "tar", strings.TrimSpace(string(image)), "-xf", "-", "-C", "/copy")
			pipe, err := read.StdoutPipe()
			if err != nil {
				return err
			}
			write.Stdin = pipe
			if err = read.Start(); err != nil {
				return err
			}
			we := write.Run()
			_ = pipe.Close()
			re := read.Wait()
			if we != nil || re != nil {
				return fmt.Errorf("private clone copy failed")
			}
		}
		// Runtime trigger/PID files are not cloned actions; identity and ledgers are.
		for _, file := range []string{"updater.json", "pause-agent", "agent.pid"} {
			_ = os.Remove(filepath.Join(base, "var/e2e", file))
		}
	}
	// A clean second exit keeps an empty directory off the client's state path.
	// The clone bind-mounts the copied profile where the client reads it.
	// --network container: shares interfaces, not /etc/hosts, and Docker
	// rejects --add-host in that mode. The entrypoint appends lab-hosts.
	// The copied file already names the lab /24. The clone rewrites
	// agent.example.invalid to the presentation control address first.
	netbirdDest := "/etc/netbird"
	args := []string{"run", "-d", "--name", name, "--stop-timeout", "25", "--privileged", "--network", "container:" + ns}
	if clone {
		netbirdDest = "/var/lib/netbird"
		pres, attachErr := s.AttachClonePresentationNetwork(ctx, ns)
		if attachErr != nil {
			return attachErr
		}
		if err := rewriteLabHost(filepath.Join(base, "etc", "lab-hosts"), "agent.example.invalid", pres.Control); err != nil {
			return err
		}
	}
	args = append(args,
		"--mount", "type=bind,src="+filepath.Join(base, "etc")+",dst=/etc/vpn-node",
		"--mount", "type=bind,src="+filepath.Join(base, "var")+",dst=/var/lib/vpn-node",
		"--mount", "type=bind,src="+filepath.Join(base, "netbird")+",dst="+netbirdDest,
		"--mount", "type=bind,src="+filepath.Join(base, "opt")+",dst=/opt/vpn-node",
		strings.TrimSpace(string(image)),
	)
	return run(args...)
}

package main

// TEST ONLY transport fault. This loopback listener uses the enrolled node's
// real mTLS identity upstream. No policy, signature, cache or database is edited.
import (
	"bytes"
